package com.team2.wellness.engagement.recap.application;
import com.team2.wellness.engagement.notification.application.NotificationService; import com.team2.wellness.engagement.port.out.*; import com.team2.wellness.engagement.recap.domain.MonthlyRecap; import com.team2.wellness.engagement.recap.persistence.MonthlyRecapRepository; import jakarta.transaction.Transactional; import java.time.YearMonth; import java.util.*; import org.springframework.stereotype.Service;
@Service @Transactional public class MonthlyRecapService {final MonthlyRecapRepository recaps;final CoreAccessPort core;final ImageGenerationPort images;final MediaStoragePort storage;final NotificationService notifications; public MonthlyRecapService(MonthlyRecapRepository r,CoreAccessPort c,ImageGenerationPort i,MediaStoragePort s,NotificationService n){recaps=r;core=c;images=i;storage=s;notifications=n;} public MonthlyRecap create(MonthlyGroupStats stats){return recaps.findByGroupIdAndRecapMonth(stats.groupId(),stats.month()).orElseGet(()->{String summary="이번 달, 함께 " + stats.completedCount()+"번의 루틴을 완주했어요. 다음 달도 서로를 응원해요!"; MonthlyRecap recap=recaps.save(new MonthlyRecap(stats.groupId(),stats.month(),summary)); try{var image=images.generate(new ImageGenerationPort.ImageCommand("A positive, calm Korean wellness group monthly recap illustration. No text or logos.",new byte[0],"image/png"));recap.attachImage(storage.storeAiOutput(stats.groupId(),image.bytes(),image.contentType()).objectKey());}catch(RuntimeException ignored){} core.getGroupMemberIds(stats.groupId()).forEach(member->notifications.create(member,"MONTHLY_RECAP",summary));return recap;});} public record MonthlyGroupStats(UUID groupId,YearMonth month,long completedCount,long totalCount){public MonthlyGroupStats{Objects.requireNonNull(groupId);Objects.requireNonNull(month);if(completedCount<0||totalCount<0)throw new IllegalArgumentException("Counts must be non-negative");}} }
